async def act(page):
    """
    From the current UI state: navigate to the Sample Page (using a relative goto),
    locate the visible search input using accessibility roles, perform a search for
    the keyword 'playbook', wait for results to render in role='main', then click
    the second-to-last result (prefer clicking the first link inside that article).

    The navigation-causing click (the result click) is the final action.
    """

    # Navigate to the Sample Page using a relative goto (do not click an intermediate link
    # because the final click must be the only navigation-causing action at the end).
    await page.goto('/?page_id=2')
    await page.wait_for_load_state('networkidle')

    # Locate a complementary region and prefer a role=searchbox inside it; fall back to textbox.
    search_input = None
    try:
        comp_count = await page.get_by_role('complementary').count()
    except Exception:
        comp_count = 0

    if comp_count > 0:
        comp = page.get_by_role('complementary').nth(0)
        try:
            sb_count = await comp.get_by_role('searchbox').count()
        except Exception:
            sb_count = 0
        if sb_count > 0:
            search_input = comp.get_by_role('searchbox').nth(0)
        else:
            try:
                tb_count = await comp.get_by_role('textbox').count()
            except Exception:
                tb_count = 0
            if tb_count > 0:
                search_input = comp.get_by_role('textbox').nth(0)
    else:
        # No complementary region found; try global searchbox/textbox
        try:
            sb_count = await page.get_by_role('searchbox').count()
        except Exception:
            sb_count = 0
        if sb_count > 0:
            search_input = page.get_by_role('searchbox').nth(0)
        else:
            try:
                tb_count = await page.get_by_role('textbox').count()
            except Exception:
                tb_count = 0
            if tb_count > 0:
                search_input = page.get_by_role('textbox').nth(0)

    if search_input is None:
        raise Exception("Could not locate an accessible search input to perform the 'playbook' query.")

    # Fill the search term 'playbook'. Use fill when possible; fallback to click+type.
    try:
        await search_input.fill('playbook')
    except Exception:
        await search_input.click()
        await page.keyboard.type('playbook')

    # Trigger the search. Prefer a button inside the complementary region whose name contains 'search'.
    triggered = False
    if comp_count > 0:
        comp = page.get_by_role('complementary').nth(0)
        try:
            btn_count = await comp.get_by_role('button').count()
        except Exception:
            btn_count = 0
        if btn_count > 0:
            target_btn = None
            for i in range(btn_count):
                btn = comp.get_by_role('button').nth(i)
                try:
                    name = (await btn.inner_text()).strip()
                except Exception:
                    name = ''
                if 'search' in name.lower():
                    target_btn = btn
                    break
            if target_btn is None:
                target_btn = comp.get_by_role('button').nth(0)
            await target_btn.click()
            triggered = True

    if not triggered:
        # Try a global button with 'search' in its name
        try:
            global_btn_count = await page.get_by_role('button').count()
        except Exception:
            global_btn_count = 0
        target_btn = None
        for i in range(global_btn_count):
            btn = page.get_by_role('button').nth(i)
            try:
                name = (await btn.inner_text()).strip()
            except Exception:
                name = ''
            if 'search' in name.lower():
                target_btn = btn
                break
        if target_btn is not None:
            await target_btn.click()
            triggered = True

    if not triggered:
        # Final fallback: press Enter in the search input
        await search_input.press('Enter')

    # Wait for results to appear in role='main'
    main = page.get_by_role('main')
    try:
        await main.wait_for(state='visible', timeout=5000)
    except Exception:
        await page.wait_for_load_state('networkidle')

    # Gather article children and click the second-to-last result
    articles = main.get_by_role('article')
    articles_count = await articles.count()

    if articles_count == 0:
        raise Exception("No article results found after searching for 'playbook'.")

    idx = articles_count - 2 if articles_count >= 2 else 0

    # Prefer clicking the first link inside the target article; if no link, click the article itself.
    target_article = main.get_by_role('article').nth(idx)
    try:
        links_count = await target_article.get_by_role('link').count()
    except Exception:
        links_count = 0

    if links_count > 0:
        # Final action: click the first link inside the chosen article
        await main.get_by_role('article').nth(idx).get_by_role('link').nth(0).click()
    else:
        # Fallback final action: click the article container
        await main.get_by_role('article').nth(idx).click()

